# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_23_444_2", r"в условии потеряна десятичная запятая: «$|\sqrt2-1$, $5|$» вместо $|\sqrt2-1{,}5|$; ключ $1{,}5-\sqrt2$ верен ($\sqrt2\approx1{,}414<1{,}5$)",
  q=r"Запишите без знака модуля: б) $|\sqrt{2} - 1{,}5|$;")
E("G9_TB_23_444_4", r"в условии потеряна десятичная запятая: «$|\sqrt3-1$, $7|$» вместо $|\sqrt3-1{,}7|$; ключ $\sqrt3-1{,}7$ верен ($\sqrt3\approx1{,}732>1{,}7$)",
  q=r"Запишите без знака модуля: г) $|\sqrt{3} - 1{,}7|$.")
E("G9_TB_23_445_2", r"$y=x^{2}-12x+34=(x-6)^{2}-2$: вершина $(6;-2)$ лежит в IV четверти, график содержит точки I, II (при $x<6-\sqrt2$ и $x>6+\sqrt2$, $y>0$) и IV (при $6-\sqrt2<x<6+\sqrt2$, $y<0$); в III четверти точек нет ($x<0\Rightarrow y>34>0$). В ключе было «III и IV»",
  k=r"только $III$",
  dnew={0: (r"$I$ и $II$", r"Ученик перепутал знак вершины и решил, что график целиком выше оси $Ox$; но $y(6)=-2<0$, поэтому график заходит в IV четверть."),
        1: (r"$III$ и $IV$", r"Ученик верно нашёл, что при $x<0$ значения $y$ положительны (III четверти нет), но решил, что и в IV четверти точек нет; вершина $(6;-2)$ лежит именно в IV четверти."),
        },
  dadd=[(r"$II$ и $III$", r"Ученик принял, что парабола с ветвями вверх лежит правее оси $Oy$; но при $x<0$ значения $y=x^{2}-12x+34>0$, то есть в II четверти точки есть.")])
E("G9_TB_22_435", r"новая деталь на $0{,}2$ кг легче: $n$ — масса новой, $n+0{,}2$ — старой; $\frac{22}{n}=\frac{24}{n+0{,}2}+2\Rightarrow n^{2}+1{,}2n-2{,}2=0\Rightarrow n=1$; новая $1{,}0$ кг, старая $1{,}2$ кг. Ключ «$1{,}2;\,1{,}0$» в порядке вопроса («нового и старого») означал бы новая $1{,}2$, старая $1{,}0$ — обратное",
  k=r"новой детали — $1{,}0$ кг, старой — $1{,}2$ кг",
  dnew={0: (r"новой детали — $1{,}2$ кг, старой — $1{,}0$ кг", r"Ученик получил верные числа $1{,}0$ и $1{,}2$, но перепутал, какая деталь легче: новая на $0{,}2$ кг легче старой, поэтому новая — $1{,}0$ кг."),
        1: (r"новой детали — $0{,}8$ кг, старой — $1{,}0$ кг", r"Ученик неверно решил уравнение $\frac{22}{n}-\frac{24}{n+0{,}2}=2$: потерял знак при приведении к общему знаменателю и получил $n=0{,}8$."),
        2: (r"новой детали — $1{,}2$ кг, старой — $1{,}4$ кг", r"Ученик прочитал условие «нового типа на $0{,}2$ кг легче» как «старой типа на $0{,}2$ кг тяжелее нового» и взял в качестве старой массы $n+0{,}2$ от неверного значения $n=1{,}2$.")})
